 record['refs']=list(dict.fromkeys(record['refs']))
 if record["id"] in {"C-SA14-245","C-SA14-253","C-SA14-256","C-SA14-265","C-SA14-266","C-SA14-267"}: record["refs"].append("Kleiman1971SGA6XIII")
 if record["id"] in {"C-SA14-240","C-SA14-269"}: record["refs"].append("RaynaudKleiman1971SGA6XII")
